        // Message: Unexpected token 'a', "an invalid JSON" is not valid JSON

        println("Stacktrace:")
        // Stacktrace:

        // Prints the full JavaScript stack trace 
        e.printStackTrace()
    }
}","title":"Kotlin/Wasm JavaScript interoperability","source":"https://kotlinlang.org/docs/wasm-js-interop.html","sections":["Interoperability with JavaScript > Exception handling"],"line_start":353,"line_end":383,"score":0.6048415899276733,"release_version":null,"availability":"unknown"}]}

